#include <format>
#include <iostream>
#include <string>
#include <string_view>
#include <vector>

// The version that builds its own logger. Nothing outside it can see what it logged.
class ConsoleLogger {
 public:
  void warn(std::string_view line) const { std::cout << std::format("[warn] {}\n", line); }
};

class WiredMonitor {
 public:
  explicit WiredMonitor(int limit_percent) : limit_percent_(limit_percent) {}
  void on_charge(int percent) const {
    if (percent < limit_percent_) logger_.warn(std::format("battery at {}%", percent));
  }

 private:
  ConsoleLogger logger_;
  int limit_percent_;
};

// The injected version. The interface belongs to the monitor, not to the console.
class Logger {
 public:
  Logger() = default;
  Logger(const Logger&) = delete;
  Logger& operator=(const Logger&) = delete;
  virtual ~Logger() = default;
  virtual void warn(std::string_view line) = 0;
};

class BatteryMonitor {
 public:
  BatteryMonitor(Logger& logger, int limit_percent) : logger_(logger), limit_percent_(limit_percent) {}
  void on_charge(int percent) const {
    if (percent < limit_percent_) logger_.warn(std::format("battery at {}%", percent));
  }

 private:
  Logger& logger_;
  int limit_percent_;
};

class RecordingLogger final : public Logger {
 public:
  void warn(std::string_view line) override { lines_.emplace_back(line); }
  [[nodiscard]] const std::vector<std::string>& lines() const { return lines_; }

 private:
  std::vector<std::string> lines_;
};

int main() {
  const WiredMonitor wired(20);
  wired.on_charge(15);  // the only place this line can be read is stdout

  RecordingLogger fake;
  const BatteryMonitor monitor(fake, 20);
  monitor.on_charge(55);
  monitor.on_charge(15);
  monitor.on_charge(4);
  std::cout << std::format("fake logger saw {} lines\n", fake.lines().size());
  for (const std::string& line : fake.lines()) std::cout << std::format("  {}\n", line);
}

