#include <chrono>
#include <format>
#include <iostream>
#include <thread>

using namespace std::chrono_literals;

class WiredWatchdog {
 public:
  explicit WiredWatchdog(std::chrono::milliseconds timeout)
      : timeout_(timeout), last_(std::chrono::steady_clock::now()) {}

  void on_odometry() { last_ = std::chrono::steady_clock::now(); }

  [[nodiscard]] bool is_late() const { return std::chrono::steady_clock::now() - last_ > timeout_; }

 private:
  std::chrono::milliseconds timeout_;
  std::chrono::steady_clock::time_point last_;
};

int main() {
  const WiredWatchdog fresh(200ms);
  std::cout << std::format("straight after a message: late = {}\n", fresh.is_late());

  WiredWatchdog quiet(200ms);
  std::this_thread::sleep_for(600ms);  // the only way to reach the timeout
  std::cout << std::format("after sleeping 600 ms:    late = {}\n", quiet.is_late());
  quiet.on_odometry();
  std::cout << std::format("after a message arrives:  late = {}\n", quiet.is_late());
}

#include <chrono>
#include <format>
#include <iostream>
#include <optional>
#include <string>
#include <string_view>
#include <vector>

using namespace std::chrono_literals;

// Everything the watchdog needs from a clock, and nothing else.
class Clock {
 public:
  Clock() = default;
  Clock(const Clock&) = delete;
  Clock& operator=(const Clock&) = delete;
  virtual ~Clock() = default;
  [[nodiscard]] virtual std::chrono::nanoseconds now() const = 0;
};

class SteadyClock final : public Clock {  // what the node passes in production
 public:
  [[nodiscard]] std::chrono::nanoseconds now() const override {
    return std::chrono::steady_clock::now().time_since_epoch();
  }
};

class FakeClock final : public Clock {  // what the test passes
 public:
  [[nodiscard]] std::chrono::nanoseconds now() const override { return now_; }
  void advance(std::chrono::nanoseconds step) { now_ += step; }

 private:
  std::chrono::nanoseconds now_{};
};

class Logger {
 public:
  Logger() = default;
  Logger(const Logger&) = delete;
  Logger& operator=(const Logger&) = delete;
  virtual ~Logger() = default;
  virtual void warn(std::string_view line) = 0;
};

class RecordingLogger final : public Logger {
 public:
  void warn(std::string_view line) override { lines_.emplace_back(line); }
  [[nodiscard]] const std::vector<std::string>& lines() const { return lines_; }

 private:
  std::vector<std::string> lines_;
};

class Watchdog {
 public:
  Watchdog(const Clock& clock, Logger& logger, std::chrono::nanoseconds timeout)
      : clock_(clock), logger_(logger), timeout_(timeout) {}

  void on_odometry() { last_ = clock_.now(); }

  // How long since the last message, or nothing when none has arrived.
  [[nodiscard]] std::optional<std::chrono::nanoseconds> silence() const {
    if (!last_) return std::nullopt;
    return clock_.now() - *last_;
  }

  void poll() {
    const std::optional<std::chrono::nanoseconds> quiet = silence();
    const bool late = quiet && *quiet > timeout_;
    if (late && !late_)
      logger_.warn(std::format("no odometry for {}", std::chrono::duration_cast<std::chrono::milliseconds>(*quiet)));
    late_ = late;
  }

  [[nodiscard]] bool is_late() const { return late_; }

 private:
  const Clock& clock_;
  Logger& logger_;
  std::chrono::nanoseconds timeout_;
  std::optional<std::chrono::nanoseconds> last_;
  bool late_ = false;
};

int main() {
  FakeClock clock;
  RecordingLogger log;
  Watchdog dog(clock, log, 200ms);

  const auto step = [&](std::chrono::milliseconds by, bool message) {
    clock.advance(by);
    if (message) dog.on_odometry();
    dog.poll();
    std::cout << std::format("t = {:>6}: {}{}\n", std::chrono::duration_cast<std::chrono::milliseconds>(clock.now()),
                             dog.is_late() ? "late" : "fresh", message ? ", odometry arrived" : "");
  };

  step(0ms, true);
  step(100ms, false);
  step(150ms, false);
  step(150ms, false);
  step(0ms, true);
  step(50ms, false);
  step(300ms, false);

  // A 30 second timeout, tested in the same instant.
  FakeClock slow_clock;
  RecordingLogger slow_log;
  Watchdog slow(slow_clock, slow_log, 30s);
  slow.on_odometry();
  slow_clock.advance(31s);
  slow.poll();

  std::cout << std::format("recorded {} warnings from the 200 ms watchdog:\n", log.lines().size());
  for (const std::string& line : log.lines()) std::cout << std::format("  {}\n", line);
  std::cout << std::format("the 30 s watchdog recorded: {}\n", slow_log.lines().front());
}

#include <algorithm>
#include <chrono>
#include <cstdint>
#include <format>
#include <iostream>
#include <optional>
#include <string>
#include <string_view>
#include <vector>

using namespace std::chrono_literals;

struct Limit {
  std::int32_t max_mdeg_per_s;
};

class Clock {
 public:
  Clock() = default;
  Clock(const Clock&) = delete;
  Clock& operator=(const Clock&) = delete;
  virtual ~Clock() = default;
  [[nodiscard]] virtual std::chrono::nanoseconds now() const = 0;
};

class Logger {
 public:
  Logger() = default;
  Logger(const Logger&) = delete;
  Logger& operator=(const Logger&) = delete;
  virtual ~Logger() = default;
  virtual void warn(std::string_view line) = 0;
};

class JointGuard {
 public:
  JointGuard(const Clock& clock, Logger& logger, Limit limit, std::chrono::nanoseconds quiet)
      : clock_(clock), logger_(logger), limit_(limit), quiet_(quiet) {}

  [[nodiscard]] std::int32_t apply(std::int32_t command_mdeg_per_s) {
    const std::int32_t clamped = std::clamp(command_mdeg_per_s, -limit_.max_mdeg_per_s, limit_.max_mdeg_per_s);
    if (clamped != command_mdeg_per_s && ready_to_warn()) {
      last_warning_ = clock_.now();
      logger_.warn(std::format("clamped {} to {} mdeg/s", command_mdeg_per_s, clamped));
    }
    return clamped;
  }

  // How long since the last warning, or nothing when none has been logged.
  [[nodiscard]] std::optional<std::chrono::nanoseconds> since_last_warning() const {
    if (!last_warning_) return std::nullopt;
    return clock_.now() - *last_warning_;
  }

 private:
  [[nodiscard]] bool ready_to_warn() const {
    const std::optional<std::chrono::nanoseconds> age = since_last_warning();
    return !age || *age >= quiet_;
  }

  const Clock& clock_;
  Logger& logger_;
  Limit limit_;
  std::chrono::nanoseconds quiet_;
  std::optional<std::chrono::nanoseconds> last_warning_;
};

class FakeClock final : public Clock {
 public:
  [[nodiscard]] std::chrono::nanoseconds now() const override { return now_; }
  void advance(std::chrono::nanoseconds step) { now_ += step; }

 private:
  std::chrono::nanoseconds now_{};
};

class RecordingLogger final : public Logger {
 public:
  void warn(std::string_view line) override { lines_.emplace_back(line); }
  [[nodiscard]] const std::vector<std::string>& lines() const { return lines_; }

 private:
  std::vector<std::string> lines_;
};

int main() {
  FakeClock clock;
  RecordingLogger log;
  JointGuard guard(clock, log, Limit{.max_mdeg_per_s = 1500}, 1s);

  // apply() runs first and the count is read afterwards: the order of two arguments would be unspecified.
  const auto report = [&](std::string_view step, std::int32_t asked, std::int32_t got) {
    std::cout << std::format("{}: apply({:>5}) = {:>5}, warnings so far {}\n", step, asked, got, log.lines().size());
  };

  report("1. inside the limit      ", 900, guard.apply(900));

  for (int k = 0; k < 5; ++k) {
    clock.advance(5ms);
    const std::int32_t got = guard.apply(2400);
    if (k == 0) report("2. first over the limit  ", 2400, got);
    if (k == 4) report("2. fifth over the limit  ", 2400, got);
  }

  clock.advance(1s);
  const std::int32_t after_quiet = guard.apply(2400);
  report("3. after the quiet period", 2400, after_quiet);

  clock.advance(2s);
  const std::int32_t below = guard.apply(-9000);
  report("4. below the low limit   ", -9000, below);

  clock.advance(250ms);
  std::cout << "the fake logger recorded:\n";
  for (const std::string& line : log.lines()) std::cout << std::format("  {}\n", line);
  std::cout << std::format("since the last warning: {}\n",
                           std::chrono::duration_cast<std::chrono::milliseconds>(*guard.since_last_warning()));
}

#include <chrono>
#include <cstdint>
#include <format>
#include <functional>
#include <iostream>
#include <memory>

class Clock {
 public:
  Clock() = default;
  Clock(const Clock&) = delete;
  Clock& operator=(const Clock&) = delete;
  virtual ~Clock() = default;
  [[nodiscard]] virtual std::chrono::nanoseconds now() const = 0;
};

class SteadyClock final : public Clock {
 public:
  [[nodiscard]] std::chrono::nanoseconds now() const override {
    return std::chrono::steady_clock::now().time_since_epoch();
  }
};

// The same clock with no base class, for the template version.
struct PlainSteadyClock {
  [[nodiscard]] std::chrono::nanoseconds now() const { return std::chrono::steady_clock::now().time_since_epoch(); }
};

struct ByReference {
  const Clock& clock;
  std::int64_t timeout_ns;
};

struct ByOwner {
  std::unique_ptr<Clock> clock;
  std::int64_t timeout_ns;
};

struct ByCallable {
  std::function<std::chrono::nanoseconds()> clock;
  std::int64_t timeout_ns;
};

template <typename C>
struct ByTemplate {
  [[no_unique_address]] C clock;
  std::int64_t timeout_ns;
};

int main() {
  std::cout << std::format("reference to an interface:  {} bytes, plus the object the caller owns\n",
                           sizeof(ByReference));
  std::cout << std::format("unique_ptr to an interface: {} bytes, plus {} on the heap\n", sizeof(ByOwner),
                           sizeof(SteadyClock));
  std::cout << std::format("std::function:              {} bytes\n", sizeof(ByCallable));
  std::cout << std::format("template parameter:         {} bytes, nothing else\n",
                           sizeof(ByTemplate<PlainSteadyClock>));
  std::cout << std::format("the timeout on its own:     {} bytes\n", sizeof(std::int64_t));
}

struct PlainReplayClock {  // the same body behind all three holders
  std::span<const std::int64_t> stamps;
  mutable std::int64_t at = 0;
  [[nodiscard]] std::chrono::nanoseconds now() const {
    at = (at + 1) & 2047;  // 2048 stamps, 16 KB, resident in L1
    return std::chrono::nanoseconds{stamps[static_cast<std::size_t>(at)]};
  }
};
// The timed loop, written once per holder; only the type of `clock` changes.
