#include <chrono>
#include <concepts>
#include <utility>

template <typename C>
concept MonotonicClock = requires(const C& clock) {
  { clock.now() } -> std::same_as<std::chrono::nanoseconds>;
};

template <MonotonicClock C>
class Watchdog {
 public:
  explicit Watchdog(C clock, std::chrono::nanoseconds timeout) : clock_(std::move(clock)), timeout_(timeout) {}
  [[nodiscard]] bool is_late(std::chrono::nanoseconds last) const { return clock_.now() - last > timeout_; }

 private:
  [[no_unique_address]] C clock_;
  std::chrono::nanoseconds timeout_;
};

// The fake the test writes, with the clock spelled in milliseconds by mistake.
struct FakeClock {
  std::chrono::milliseconds stamp{};
  [[nodiscard]] std::chrono::milliseconds now() const { return stamp; }
};

int main() {
  const Watchdog dog(FakeClock{}, std::chrono::nanoseconds{200});
  return dog.is_late(std::chrono::nanoseconds{0}) ? 1 : 0;
}

#include <cstddef>
#include <format>
#include <iostream>
#include <memory>
#include <string>
#include <string_view>
#include <vector>

class Logger {
 public:
  Logger() = default;
  Logger(const Logger&) = delete;
  Logger& operator=(const Logger&) = delete;
  virtual ~Logger() = default;
  virtual void warn(std::string_view line) = 0;
};

class RecordingLogger final : public Logger {
 public:
  void warn(std::string_view line) override { lines_.emplace_back(line); }
  [[nodiscard]] std::size_t count() const { return lines_.size(); }

 private:
  std::vector<std::string> lines_;
};

class BatteryMonitor {
 public:
  explicit BatteryMonitor(Logger& logger) : logger_(logger) {}
  void on_charge(int percent) const {
    if (percent < 20) logger_.warn(std::format("battery at {}%", percent));
  }

 private:
  Logger& logger_;  // the monitor does not own this
};

int main() {
  auto log = std::make_unique<RecordingLogger>();
  const BatteryMonitor monitor(*log);
  monitor.on_charge(15);
  std::cout << std::format("logged {} line\n", log->count());
  log.reset();           // the owner tears the logger down first
  monitor.on_charge(4);  // and the monitor writes into it anyway
}
